-- PT119-S3-Q5. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT119-S3-Q5$batch11$ AND q.stimulus=$batch11$Psychologist: Because of a perceived social stigma against psychotherapy, and because of age discrimination on the part of some professionals, some elderly people feel discouraged about trying psychotherapy. They should not be, however, for many younger people have greatly benefited from it, and people in later life have certain advantages over the young—such as breadth of knowledge, emotional maturity, and interpersonal skills—that contribute to the likelihood of a positive outcome.$batch11$ AND q.prompt=$batch11$Which one of the following most accurately expresses the main conclusion of the psychologist's argument?$batch11$ AND q.correct_choice=$batch11$C$batch11$) THEN RAISE EXCEPTION 'Question changed: PT119-S3-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT119-S3-Q5$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S3-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT119-S3-Q5$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Opposing Point$batch11$, $batch11$Because of stigma and age discrimination, some elderly people feel discouraged about trying psychotherapy.$batch11$), (1, $batch11$Conclusion$batch11$, $batch11$They should not be discouraged.$batch11$), (2, $batch11$Evidence$batch11$, $batch11$Many younger people have benefited greatly, and older people have advantages that make a good outcome more likely.$batch11$), (3, $batch11$Evaluate$batch11$, $batch11$"They should not be, however" is the pivot, and "for" introduces the support. Swap "they" for the elderly and "be" for discouraged: elderly people should not be discouraged from trying psychotherapy.$batch11$), (4, $batch11$Goal$batch11$, $batch11$Elderly people should not be reluctant to try psychotherapy.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT119-S3-Q5$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Age discrimination by some professionals is background for why the elderly feel discouraged.$batch11$), ($batch11$B$batch11$, $batch11$The elderly have advantages that make success likely. Nothing says they benefit more than the young.$batch11$), ($batch11$C$batch11$, $batch11$This is the pivot sentence with "they" and "be" filled in.$batch11$), ($batch11$D$batch11$, $batch11$Maturity helping is support for the conclusion, not the conclusion.$batch11$), ($batch11$E$batch11$, $batch11$The passage never compares how willing the elderly and the young are to try it.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT119-S3-Q5$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
